<template>
  <div class="columns is-mobile is-multiline">
    <div class="column is-narrow">
      <div class="control">
        <button
          class="button is-primary"
          :class="{ 'is-loading': isLoading }"
          @click="$emit('save', comment)"
          v-translate
        >
          Save
        </button>
      </div>
    </div>
    <div class="column is-narrow">
      <button class="button" @click="$emit('preview')">
        <fa-icon icon="eye" />
        <span>&nbsp;</span>
        <span v-translate>Preview</span>
      </button>
    </div>
    <div class="column is-12-mobile">
      <div class="control is-expanded">
        <input
          v-model="comment"
          type="text"
          class="input"
          :disabled="mode !== 'edit'"
          :placeholder="$gettext('comment')"
        />
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue';
import { useRoute } from 'vue-router';

defineProps({
  isLoading: {
    type: Boolean,
    required: true,
  },
});
defineEmits(['preview', 'save']);

const route = useRoute();

const comment = ref('');

const mode = computed(() => {
  return String(route.name).split('-')[1]; // right part of route name : add or edit
});
</script>
